    # 3 - (401) POST:/api/v1/agents/{agent_id}/instance/{instance_id}/offline
    # Found 3 potential faults. Type-codes: 101, 205
    @timeout_decorator.timeout(60)
    def test_95_post_on_offline_showsFaults_101_205(self):
        
        headers = {}
        headers["content-type"] = "application/json"
        body = " { " + \
            " \"email\" : \"admin\", " + \
            " \"password\" : \"Adm1n-Bamf-Thesis-2026\" " + \
            " } "
        res_admin = requests \
                .post("http://localhost:8211/login", 
                    headers=headers, data=body, allow_redirects=False, verify=False)
        token_admin =  res_admin.json()["token"]
        
        auth_admin = "Bearer " + token_admin
        headers = {}
        headers["content-type"] = "application/json"
        body = " { " + \
            " \"email\" : \"viewer\", " + \
            " \"password\" : \"V1ewer-Bamf-Thesis-2026\" " + \
            " } "
        res_viewer = requests \
                .post("http://localhost:8211/login", 
                    headers=headers, data=body, allow_redirects=False, verify=False)
        token_viewer =  res_viewer.json()["token"]
        
        auth_viewer = "Bearer " + token_viewer
        
        # Fault101. Received A Response From API With A Structure/Data That Is Not Matching Its Schema. Type: validation.response.status.unknown Response status 401 not defined for path '/api/v1/roles/{role_name}'.
        headers = {}
        headers["Authorization"] = auth_admin # admin
        headers['Accept'] = "application/json"
        res_0 = requests \
                .get(self.baseUrlOfSut + "/api/v1/roles/admin",
                    headers=headers, timeout=EM_HTTP_TIMEOUT_S, verify=False)
        
        assert res_0.status_code == 401
        assert "Bearer" in res_0.headers["www-authenticate"]
        assert "application/json" in res_0.headers["content-type"]
        assert res_0.json()["detail"] == "Not authenticated"
        
        headers = {}
        headers["Authorization"] = auth_viewer # viewer
        headers['Accept'] = "application/json"
        res_1 = requests \
                .get(self.baseUrlOfSut + "/api/v1/roles/admin",
                    headers=headers, timeout=EM_HTTP_TIMEOUT_S, verify=False)
        
        assert res_1.status_code == 200
        assert "application/json" in res_1.headers["content-type"]
        assert res_1.json()["created_at"] == "2025-01-01T00:00:00Z"
        assert res_1.json()["updated_at"] == "2025-01-01T00:00:00Z"
        assert res_1.json()["name"] == "admin"
        assert res_1.json()["description"] == "Unrestricted access to all resources and platform operations"
        assert res_1.json()["is_builtin"] == True
        assert len(res_1.json()["allow"]["labels"]) == 0
        assert len(res_1.json()["allow"]["names"]) == 0
        assert len(res_1.json()["deny"]["labels"]) == 0
        assert len(res_1.json()["deny"]["names"]) == 0
        assert len(res_1.json()["kubernetes_groups"]) == 0
        
        # Fault101. Received A Response From API With A Structure/Data That Is Not Matching Its Schema. Type: validation.response.status.unknown Response status 401 not defined for path '/api/v1/agents/{agent_id}/instance/{instance_id}/offline'.
        # Fault205. Wrongly Not Recognized as Authenticated.
        headers = {}
        headers["X-Bamf-Client-Cert"] = ""
        headers["Authorization"] = auth_viewer # viewer
        headers['Accept'] = "application/json"
        res_2 = requests \
                .post(self.baseUrlOfSut + "/api/v1/agents/a2ZrK2ZK9cc4/instance/S48chhN3fRKgRz3j/offline",
                    headers=headers, timeout=EM_HTTP_TIMEOUT_S, verify=False)
        
        assert res_2.status_code == 401
        assert "www-authenticate" not in res_2.headers
        assert "application/json" in res_2.headers["content-type"]
        assert res_2.json()["detail"] == "Missing X-Bamf-Client-Cert header"
    
    
    # Calls:
    # (401) POST:/api/v1/agents/{agent_id}/instance/{instance_id}/offline
    # Found 1 potential fault of type-code 101
    @timeout_decorator.timeout(60)
    def test_96_post_on_offline_returnsMismatchResponseWithSchema(self):
        
        # Fault101. Received A Response From API With A Structure/Data That Is Not Matching Its Schema. Type: validation.response.status.unknown Response status 401 not defined for path '/api/v1/agents/{agent_id}/instance/{instance_id}/offline'.
        headers = {}
        headers["X-Bamf-Client-Cert"] = "bLLKQk_lCvhM9TNs"
        headers['Accept'] = "application/json"
        res_0 = requests \
                .post(self.baseUrlOfSut + "/api/v1/agents/J2dBuO/instance/wu76Muw/offline",
                    headers=headers, timeout=EM_HTTP_TIMEOUT_S, verify=False)
        
        assert res_0.status_code == 401
        assert "www-authenticate" not in res_0.headers
        assert "application/json" in res_0.headers["content-type"]
        assert res_0.json()["detail"] == "Invalid certificate format"


